CREATE TABLE `alert_states` (`key` text,`target_type` text NOT NULL,`target_id` text NOT NULL,`active` numeric NOT NULL,`since` integer NOT NULL,`recovery_since` integer NOT NULL,`last_observed_at` integer NOT NULL,PRIMARY KEY (`key`));
CREATE INDEX `idx_alert_states_target_id` ON `alert_states`(`target_id`);
CREATE INDEX `idx_alert_states_target_type` ON `alert_states`(`target_type`);
CREATE TABLE `api_tokens` (`id` integer PRIMARY KEY AUTOINCREMENT,`user_id` integer NOT NULL,`hash` text NOT NULL,`credential_version` integer NOT NULL,`name` text NOT NULL,`prefix` text NOT NULL,`scopes` text NOT NULL,`created_at` integer NOT NULL,`expires_at` integer NOT NULL,`last_used_at` integer NOT NULL DEFAULT 0,CONSTRAINT `fk_api_tokens_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE INDEX `idx_api_tokens_expires_at` ON `api_tokens`(`expires_at`);
CREATE UNIQUE INDEX `idx_api_tokens_hash` ON `api_tokens`(`hash`);
CREATE INDEX `idx_api_tokens_user_id` ON `api_tokens`(`user_id`);
CREATE TABLE `audit_events` (`api_token_id` integer NOT NULL DEFAULT 0,`id` text,`user_id` integer NOT NULL,`username` text NOT NULL,`action` text NOT NULL,`target` text NOT NULL,`outcome` text NOT NULL,`status` integer NOT NULL,`created_at` integer NOT NULL,PRIMARY KEY (`id`));
CREATE INDEX `idx_audit_events_action` ON `audit_events`(`action`);
CREATE INDEX `idx_audit_events_created_at` ON `audit_events`(`created_at`);
CREATE INDEX `idx_audit_events_target` ON `audit_events`(`target`);
CREATE INDEX `idx_audit_events_user_id` ON `audit_events`(`user_id`);
CREATE TABLE `backup_policies` (`server_id` text,`storage` text NOT NULL,`local_keep_last` integer NOT NULL,`local_max_age_days` integer NOT NULL,`remote_keep_last` integer NOT NULL,`remote_max_age_days` integer NOT NULL,PRIMARY KEY (`server_id`));
CREATE TABLE `backups` (`server_id` text,`name` text,`size` integer NOT NULL,`created_at` integer NOT NULL,`remote` numeric NOT NULL,`local` numeric NOT NULL,`store_id` text NOT NULL DEFAULT "",`key` text NOT NULL,`version` text NOT NULL DEFAULT "",`digest` text NOT NULL DEFAULT "",`deleting` numeric NOT NULL DEFAULT false,`local_deleting` numeric NOT NULL DEFAULT false,`remote_deleting` numeric NOT NULL DEFAULT false,`no_remote` numeric NOT NULL DEFAULT false,`error` text NOT NULL DEFAULT "",PRIMARY KEY (`server_id`,`name`));
CREATE TABLE `ember_updates` (`ember_id` text,`url` text NOT NULL,`checked_at` integer NOT NULL,`available` numeric NOT NULL,`error` text NOT NULL,PRIMARY KEY (`ember_id`),CONSTRAINT `fk_ember_updates_ember` FOREIGN KEY (`ember_id`) REFERENCES `embers`(`id`) ON DELETE CASCADE);
CREATE TABLE `embers` (`id` text,`name` text NOT NULL,`definition` text NOT NULL,`created_at` text NOT NULL,PRIMARY KEY (`id`));
CREATE INDEX `idx_embers_name` ON `embers`(`name`);
CREATE TABLE `notification_deliveries` (`notification_id` integer,`state` text NOT NULL,`attempts` integer NOT NULL,`next_attempt_at` integer NOT NULL,`delivered_at` integer NOT NULL,`error` text NOT NULL,PRIMARY KEY (`notification_id`),CONSTRAINT `fk_notification_deliveries_notification` FOREIGN KEY (`notification_id`) REFERENCES `notifications`(`id`) ON DELETE CASCADE);
CREATE INDEX `notification_delivery_due` ON `notification_deliveries`(`state`,`next_attempt_at`);
CREATE TABLE `notification_recipients` (`notification_id` integer,`user_id` integer,`read_at` integer NOT NULL DEFAULT 0,PRIMARY KEY (`notification_id`,`user_id`),CONSTRAINT `fk_notification_recipients_notification` FOREIGN KEY (`notification_id`) REFERENCES `notifications`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_notification_recipients_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE INDEX `notification_user_unread` ON `notification_recipients`(`user_id`,`read_at`);
CREATE TABLE `notifications` (`id` integer PRIMARY KEY AUTOINCREMENT,`target_type` text NOT NULL,`target_id` text NOT NULL,`kind` text NOT NULL,`severity` text NOT NULL,`title` text NOT NULL,`body` text NOT NULL,`created_at` integer NOT NULL);
CREATE INDEX `notification_target` ON `notifications`(`target_type`,`target_id`);
CREATE TABLE `oidc_identities` (`issuer` text,`subject` text,`user_id` integer NOT NULL,PRIMARY KEY (`issuer`,`subject`),CONSTRAINT `fk_oidc_identities_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE INDEX `idx_oidc_identities_user_id` ON `oidc_identities`(`user_id`);
CREATE TABLE `role_permissions` (`role_id` integer,`permission` text,PRIMARY KEY (`role_id`,`permission`),CONSTRAINT `fk_roles_permissions` FOREIGN KEY (`role_id`) REFERENCES `roles`(`id`) ON DELETE CASCADE);
CREATE TABLE `roles` (`id` integer PRIMARY KEY AUTOINCREMENT,`name` text NOT NULL,`scope` text NOT NULL,`builtin` numeric NOT NULL,CONSTRAINT `roles_scope` CHECK (scope IN ('platform','server')));
CREATE UNIQUE INDEX `roles_name_scope` ON `roles`(lower(name),`scope`);
CREATE TABLE `schedule_runs` (`only_when_running` numeric NOT NULL DEFAULT false,`id` text,`schedule_id` text NOT NULL,`schedule_version` integer NOT NULL,`recurring` numeric NOT NULL,`retry_of` text NOT NULL,`server_id` text NOT NULL,`server_name` text NOT NULL,`user_id` integer NOT NULL,`username` text NOT NULL,`action` text NOT NULL,`content` text NOT NULL,`state` text NOT NULL,`message` text NOT NULL,`created_at` integer NOT NULL,`started_at` integer NOT NULL,`finished_at` integer NOT NULL,`polled_at` integer NOT NULL,PRIMARY KEY (`id`));
CREATE INDEX `idx_schedule_runs_created_at` ON `schedule_runs`(`created_at`);
CREATE INDEX `idx_schedule_runs_finished_at` ON `schedule_runs`(`finished_at`);
CREATE INDEX `idx_schedule_runs_polled_at` ON `schedule_runs`(`polled_at`);
CREATE INDEX `idx_schedule_runs_schedule_id` ON `schedule_runs`(`schedule_id`);
CREATE INDEX `idx_schedule_runs_server_id` ON `schedule_runs`(`server_id`);
CREATE INDEX `idx_schedule_runs_state` ON `schedule_runs`(`state`);
CREATE TABLE `schedules` (`id` text,`server_id` text NOT NULL,`name` text NOT NULL,`action` text NOT NULL,`command` text NOT NULL,`cron_expression` text NOT NULL DEFAULT "0 3 * * *",`time_zone` text NOT NULL DEFAULT "UTC",`only_when_running` numeric NOT NULL DEFAULT false,`next_run_at` integer NOT NULL,`enabled` numeric NOT NULL,`user_id` integer NOT NULL,`username` text NOT NULL,`created_at` integer NOT NULL,`version` integer NOT NULL,PRIMARY KEY (`id`),CONSTRAINT `fk_schedules_server` FOREIGN KEY (`server_id`) REFERENCES `servers`(`id`) ON DELETE CASCADE);
CREATE INDEX `idx_schedules_next_run_at` ON `schedules`(`next_run_at`);
CREATE INDEX `idx_schedules_server_id` ON `schedules`(`server_id`);
CREATE TABLE `schema_migrations` (`version` integer,PRIMARY KEY (`version`));
CREATE TABLE `server_members` (`server_id` text,`user_id` integer,`role_id` integer NOT NULL,PRIMARY KEY (`server_id`,`user_id`),CONSTRAINT `fk_server_members_server` FOREIGN KEY (`server_id`) REFERENCES `servers`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_server_members_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_server_members_role` FOREIGN KEY (`role_id`) REFERENCES `roles`(`id`) ON DELETE RESTRICT);
CREATE TABLE `server_ownerships` (`server_id` text,`user_id` integer NOT NULL,PRIMARY KEY (`server_id`),CONSTRAINT `fk_server_ownerships_server` FOREIGN KEY (`server_id`) REFERENCES `servers`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_server_ownerships_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT);
CREATE INDEX `idx_server_ownerships_user_id` ON `server_ownerships`(`user_id`);
CREATE TABLE `server_transfers` (`id` text,`server_id` text NOT NULL,`source_spark_id` text NOT NULL,`target_spark_id` text NOT NULL,`source_configuration` text NOT NULL,`target_configuration` text NOT NULL,`phase` text NOT NULL,`resume_phase` text NOT NULL DEFAULT "",`cancel_from` text NOT NULL DEFAULT "",`active` numeric NOT NULL,`error` text NOT NULL DEFAULT "",`transferred_bytes` integer NOT NULL DEFAULT 0,`total_bytes` integer NOT NULL DEFAULT 0,`digest` text NOT NULL DEFAULT "",`created_at` integer NOT NULL,`updated_at` integer NOT NULL,PRIMARY KEY (`id`));
CREATE INDEX `idx_server_transfers_active` ON `server_transfers`(`active`);
CREATE INDEX `idx_server_transfers_phase` ON `server_transfers`(`phase`);
CREATE INDEX `idx_server_transfers_source_spark_id` ON `server_transfers`(`source_spark_id`);
CREATE INDEX `idx_server_transfers_target_spark_id` ON `server_transfers`(`target_spark_id`);
CREATE UNIQUE INDEX `transfers_active_server` ON `server_transfers`(`server_id`) WHERE active = true;
CREATE TABLE `servers` (`id` text,`name` text NOT NULL,`description` text NOT NULL DEFAULT "",`spark_id` text NOT NULL,`ember_id` text NOT NULL,`image` text NOT NULL,`variables` text NOT NULL,`cpu_limit` real NOT NULL,`memory_mb` integer NOT NULL,`disk_mb` integer NOT NULL,`ports` text NOT NULL,`created_at` text NOT NULL,PRIMARY KEY (`id`),CONSTRAINT `fk_servers_spark` FOREIGN KEY (`spark_id`) REFERENCES `sparks`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_servers_ember` FOREIGN KEY (`ember_id`) REFERENCES `embers`(`id`) ON DELETE RESTRICT);
CREATE INDEX `idx_servers_ember_id` ON `servers`(`ember_id`);
CREATE INDEX `idx_servers_spark_id` ON `servers`(`spark_id`);
CREATE UNIQUE INDEX `servers_name` ON `servers`(lower(name));
CREATE TABLE `spark_enrollments` (`hash` text,`spark_id` text NOT NULL,`expires_at` integer NOT NULL,PRIMARY KEY (`hash`),CONSTRAINT `fk_spark_enrollments_spark` FOREIGN KEY (`spark_id`) REFERENCES `sparks`(`id`) ON DELETE CASCADE);
CREATE UNIQUE INDEX `idx_spark_enrollments_spark_id` ON `spark_enrollments`(`spark_id`);
CREATE TABLE `spark_identities` (`spark_id` text,`certificate_hash` text NOT NULL,`previous_certificate_hash` text NOT NULL DEFAULT "",`previous_expires_at` integer NOT NULL DEFAULT 0,`certificate` blob,PRIMARY KEY (`spark_id`),CONSTRAINT `fk_spark_identities_spark` FOREIGN KEY (`spark_id`) REFERENCES `sparks`(`id`) ON DELETE CASCADE);
CREATE TABLE `spark_roles` (`spark_id` text,`role_id` integer,PRIMARY KEY (`spark_id`,`role_id`),CONSTRAINT `fk_spark_roles_spark` FOREIGN KEY (`spark_id`) REFERENCES `sparks`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_spark_roles_role` FOREIGN KEY (`role_id`) REFERENCES `roles`(`id`) ON DELETE CASCADE);
CREATE TABLE `sparks` (`id` text,`name` text NOT NULL,`kind` text NOT NULL,`description` text NOT NULL DEFAULT "",`disabled` numeric NOT NULL DEFAULT false,`game_address` text NOT NULL DEFAULT "",`cpu_limit` real NOT NULL DEFAULT 0,`memory_mb` integer NOT NULL DEFAULT 0,`disk_mb` integer NOT NULL DEFAULT 0,`port_allocations` text NOT NULL DEFAULT '[]',`created_at` text NOT NULL,PRIMARY KEY (`id`),CONSTRAINT `sparks_kind` CHECK (kind = 'remote'));
CREATE UNIQUE INDEX `sparks_name` ON `sparks`(lower(name));
CREATE TABLE `user_sessions` (`hash` text,`provider` text NOT NULL DEFAULT "",`user_id` integer NOT NULL,`csrf` text NOT NULL,`credential_version` integer NOT NULL,`expires_at` integer NOT NULL,`last_seen_at` integer NOT NULL,PRIMARY KEY (`hash`),CONSTRAINT `fk_user_sessions_user` FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE);
CREATE INDEX `idx_user_sessions_expires_at` ON `user_sessions`(`expires_at`);
CREATE INDEX `idx_user_sessions_user_id` ON `user_sessions`(`user_id`);
CREATE TABLE `users` (`id` integer PRIMARY KEY AUTOINCREMENT,`username` text NOT NULL,`name` text NOT NULL DEFAULT "",`email` text NOT NULL DEFAULT "",`picture` text NOT NULL DEFAULT "",`password_hash` text NOT NULL,`version` integer NOT NULL,`role_id` integer NOT NULL,`disabled` numeric NOT NULL DEFAULT false,`created_at` integer NOT NULL,CONSTRAINT `fk_users_role` FOREIGN KEY (`role_id`) REFERENCES `roles`(`id`) ON DELETE RESTRICT);
CREATE INDEX `idx_users_role_id` ON `users`(`role_id`);
CREATE UNIQUE INDEX `users_username` ON `users`(lower(username));
